  "cfgshared.effortRunsDirectByDefault": "En este modelo la ejecución siempre lleva un nivel de esfuerzo (Alto, salvo que elijas otro), así que siempre se ejecuta en la API propia de Anthropic, el único lugar donde el esfuerzo tiene efecto, y cobra un nivel más.",
  "cfgshared.advancedModeHintMetered": "Ejecuta este modelo directamente en el proveedor para controlar la temperatura, la longitud de la salida y la profundidad del razonamiento. Se ejecuta en la API del fabricante: cuesta aproximadamente {n}× más.",
