  "cfgshared.effortRunsDirectMetered": "En los modelos Claude, elegir un nivel de esfuerzo ejecuta la llamada en la API propia de Anthropic (el único lugar donde el esfuerzo tiene efecto): cuesta aproximadamente {n}× más.",
  "cfgshared.effortRunsDirectMeteredPlain": "En los modelos Claude, elegir un nivel de esfuerzo ejecuta la llamada en la API propia de Anthropic (el único lugar donde el esfuerzo tiene efecto), que cuesta más.",
