  "imgcfg.nodaroImageUpscaleDesc": "Restaura el detalle y conserva el texto exactamente como está escrito. La salida mide el tamaño de la imagen multiplicado por el factor (1x mejora en el mismo tamaño), hasta 67.108.864 píxeles en total y 16.384 píxeles por lado. El precio depende del tamaño de la salida.",
