  "utilcfg.syntaxReference": "Referencia de sintaxis",
  "utilcfg.syntaxReferenceBody": ".                       identidad (entrada completa)\n.field                  acceso a un campo\n.[\"api-key\"]            acceso con corchetes (campos que no son identificadores)\n.[]                     itera el array (un valor por elemento)\n.[0]  /  .[-1]          acceso por índice (admite negativos)\n|                       pipe — pasa el resultado de la izquierda a la derecha\nselect(expr)            conserva los elementos donde expr es verdadera\n{a, b: .field}          construcción de objeto / proyección\na | contains(\"x\")       comprueba una subcadena\na | startswith(\"x\")     comprueba el prefijo\na | endswith(\"x\")       comprueba el sufijo\na | test(\"regex\")       coincidencia de regex\na and b  /  a or b      lógica booleana\nx | not                 negación booleana\n==  !=  >  <  >=  <=    operadores de comparación",
