  "vidcfg.overlapKeyframe": "Último fotograma clave — recrea el solapamiento y luego continúa",
  "vidcfg.overlapLastFrame": "Último fotograma — continúa justo desde el final",
  "vidcfg.smartCutContinuousKeyframes": "Solo busca coincidencias entre tomas continuas; los cortes intencionales se mantienen intactos. Si no se encuentra una coincidencia cercana, no se recorta ningún fotograma. Una coincidencia lograda puede acortar un poco la unión.",
  "vidcfg.smartCut": "Corte inteligente (experimental)",
  "vidcfg.cutBestPair": "Mejor par — coincidencia PSNR en el límite (predeterminado)",
  "vidcfg.cutPrerollKeepNext": "Pre-roll conservando el siguiente — oculta la unión en el solapamiento",
