  "vidcfg.originalAudio": "Audio original",
  "vidcfg.pro1080p": "Pro (1080p)",
  "vidcfg.referenceMode": "Modo de referencia",
  "vidcfg.spicy": "Picante",
  "vidcfg.standard720p": "Estándar (720p)",
  "vidcfg.subtle": "Sutil",
  "vidcfg.choose": "Elegir",
  "vidcfg.durationAutoFromClip": "La duración se establece automáticamente a partir del clip de origen.",
  "vidcfg.drivingAudioLength": "El clip dura lo mismo que su audio: {min}–{max} s (como máximo {short} s a 1440p o a 48 / 50 fps). Sin fotograma inicial es 16:9.",
  "vidcfg.durationAuto": "Auto",
  "vidcfg.durationAutoHint": "Automática: el modelo elige la duración (la del clip de origen al editar un video de referencia). Los créditos se reservan para el clip más largo (al editar un video de referencia: la duración del video de referencia más largo redondeada hacia arriba, más un segundo) y se reembolsa la diferencia hasta la duración entregada.",
  "vidcfg.wan3Note": "El precio depende de la duración y la resolución; el botón Ejecutar muestra el precio de la duración que elijas. El audio ambiente se genera con el clip. «Adaptativo» sigue la entrada conectada; el texto a video puro se renderiza en 16:9 salvo que elijas una relación concreta.",
  "vidcfg.wan3VideoRefLimits": "Wan 3.0 exige que cada clip de origen dure de 1 a 15 s, que todos los clips conectados sumen como máximo 15 s y que la duración de entrada + la de salida no superen 30 s. El proveedor comprueba estos límites cuando se ejecuta la tarea, no antes del envío.",
  "vidcfg.wan3AudioRefLimits": "Cada referencia de audio debe durar de 1 a 15 s (se comprueba antes de enviar la tarea) y todo el audio conectado debe sumar como máximo 15 s.",
  "vidcfg.viduQ4Note": "El precio depende de la duración y la resolución; el botón Ejecutar muestra el precio de la duración que elijas. Un fotograma inicial solo anima ese fotograma; al conectar imágenes o audio de referencia se pasa al modo de referencia, que necesita un prompt. La relación de aspecto se aplica solo a las ejecuciones con referencia: una ejecución con fotograma inicial conserva la forma del fotograma. El sonido se genera con el clip.",
  "vidcfg.viduQ4AudioRefLimits": "Vidu Q4 solo admite audio MP3, de 3 a 12 s por clip. Otros formatos o duraciones se rechazan antes de enviar la tarea: convierte antes el clip a MP3.",
  "vidcfg.modeKeyframes": "Fotogramas clave: fotograma inicial, fotogramas intermedios, fotograma final",
  "vidcfg.kling4FramesUsed": "{used} de {max} fotogramas para un clip de {seconds} s (inicial + intermedios + final).",
  "vidcfg.kling4FramesOverCap": "Demasiados fotogramas para un clip de {seconds} s: {used} de {max}. Quita fotogramas o alarga el clip: con 9 s o más admite 10.",
  "vidcfg.grokVideo15FramesUsed": "{used} de {max} fotogramas intermedios para un clip de {seconds} s. Se reparten de forma uniforme por el clip, uno por cada segundo entero.",
  "vidcfg.grokVideo15FramesOverCap": "Un clip de {seconds} s admite {max} fotogramas intermedios (uno por cada segundo entero, como máximo 4); los últimos {extra} se quedarán fuera. Alarga el clip para usar más.",
  "vidcfg.grokVideo15LoopNote": "Conecta la misma imagen como fotograma inicial y final para obtener un bucle perfecto.",
  "vidcfg.startFrameOnlyResolution": "{model} admite solo fotograma inicial en {resolution}: sin fotograma final, bucle ni fotogramas intermedios. Elige {fallback} o quita el fotograma final y los fotogramas intermedios.",
  "vidcfg.inBetweenFrames": "Fotogramas intermedios",
  "vidcfg.connectInBetweenFramesNote": "Las imágenes de la entrada de referencias de imagen pasan a ser los fotogramas intermedios, en este orden; arrastra para reordenar. Hasta {max}.",
  "vidcfg.keepOriginalSound": "Conservar el sonido original de los videos de referencia",
  "vidcfg.kling4Note": "Precio por segundo según la duración y la resolución. Un video de referencia suma sus propios segundos, como mínimo los del clip. Los personajes conectados se convierten en sujetos con nombre que puedes escribir como @Name. El sonido siempre se genera.",
  "vidcfg.kling4FlashNote": "Precio por segundo según la duración, en 720p. Un video de referencia suma sus propios segundos, como mínimo los del clip. Un fotograma inicial solo es exactamente el primer fotograma; junto a referencias, se une a ellas. Los personajes conectados se convierten en sujetos con nombre que puedes escribir como @Name. La referencia de voz N pasa a ser la voz del personaje N, en el orden en que se conectaron; un personaje necesita de 2 a 4 imágenes para tener voz; si no, su clip se descarta. El sonido siempre se genera.",
  "vidcfg.pixverseV6MaxNote": "Precio por segundo según la duración y la calidad; generar audio cuesta más por segundo y está activado salvo que lo desactives. Un fotograma inicial es exactamente el primer fotograma y el clip toma su forma: la relación de aspecto se aplica solo a las ejecuciones solo con texto. Sin fotograma final ni entradas de referencia.",
  "vidcfg.ltx25Note": "El sonido (diálogo, efectos, ambiente) se genera con la imagen en cada ejecución: descríbelo en el prompt. El texto entre comillas se pronuncia; escribe \"Shot 1: … Shot 2: …\" para varios planos. Sin fotograma final ni prompt negativo.",
  "vidcfg.ltx25LongClipNote": "A 1440p o a 48/50 fps un clip dura {max} s como máximo.",
  "vidcfg.ltx25FrameShapeNote": "El fotograma inicial fija la forma del clip.",
  "vidcfg.kling4KeyframesNote": "Precio por segundo según la duración y la resolución. Las referencias de imagen son los fotogramas intermedios, en orden; la duración del clip limita el total de fotogramas (3 s → 4 … 9 s o más → 10). La relación de aspecto se aplica solo cuando no hay ningún fotograma conectado. El sonido siempre se genera.",
  "vidcfg.matchResSeam": "Usar la misma resolución que el video de origen deja la unión más limpia.",
  "vidcfg.sameSeedSimilar": "La misma semilla produce resultados similares. Déjalo vacío para usar una aleatoria.",
  "vidcfg.veo31Audio": "VEO 3.1 crea audio con IA a partir del prompt. Desactívalo para un video sin sonido y después usa un nodo que añada audio.",
  "vidcfg.veoAutoTranslateNote": "Los prompts se traducen automáticamente al inglés antes de que VEO los vea (activado por defecto). Desactívalo para conservar los prompts tal cual: útil con prompts en otros idiomas o cuando importa la redacción exacta (p. ej., la frase de cierre del bucle perfecto).",
  "vidcfg.veoAutoTranslateNoteShort": "Los prompts se traducen automáticamente al inglés antes de que VEO los vea (activado por defecto). Desactívalo para conservar los prompts tal cual.",
  "vidcfg.worksBestSameFrames": "Funciona mejor cuando el fotograma inicial y el final usan la misma imagen. Sin fotograma final, el algoritmo elige el mejor punto de bucle que encuentre, pero puede que el resultado no quede continuo.",
  "vidcfg.splitsScript": "Divide tu guion en prompts por segmento. Predeterminado: Claude Opus 4.7.",
  "vidcfg.connectVideoSlider": "Conecta un video y abre su vista previa para activar el control deslizante",
  "vidcfg.descSpeechToVideo": "Genera un video de una persona hablando a partir de una imagen y un audio, con Wan 2.2 Speech-to-Video. Conecta una imagen de retrato, un audio de voz y un prompt.",
  "vidcfg.analyzeLeaveBlank": "Déjalo en blanco y conecta un video al conector de entrada para analizar un clip subido o generado.",
  "vidcfg.descVideoAnalysis": "Divide un video (máx. 10 min) en una lista de escenas con marcas de tiempo. El costo varía según la duración del video y el modelo elegido.",
  "vidcfg.descFaceSwap1": "Sustituye el rostro de un video por el rostro de una imagen de referencia.",
  "vidcfg.descFaceSwap2": "Conecta una imagen de rostro al conector naranja y un video al conector rosa.",
