  "tut.apStep4Title": "Diez diapositivas",
  "tut.apStep4Line": "El guion se convierte en filas.",
  "tut.apStep5Title": "Una imagen para cada una",
  "tut.apStep5Line": "Una imagen por diapositiva, en secuencia.",
  "tut.apStep6Line": "Gancho, pregunta, hashtags.",
  "tut.apStep7Title": "Da formato y publica",
  "tut.apStep7Line": "Con el tamaño del feed y luego publicado.",
  "tut.apOtherSlides": "Las otras nueve diapositivas",
  "tut.apCaptionLabel": "El pie de foto que escribió",
  "tut.apPostCaption": "diapositiva {n} de 10, feed cuadrado",
  "tut.mrcRole1": "la persona",
  "tut.mrcRole2": "el sombrero",
  "tut.mrcRole3": "la pintura facial",
  "tut.mrcRole4": "la chaqueta",
  "tut.mrcRole5": "el lugar + el color de la camiseta",
  "tut.mrcContrib1": "quién es la persona",
  "tut.mrcContrib3": "pintura facial, solo en la mejilla derecha",
  "tut.mrcContrib5": "el lugar y el color de la camiseta",
  "tut.mrcDefaultHint": "Pasa el cursor sobre cualquier token rosa del prompt. La referencia a la que apunta se ilumina a la izquierda y su función aparece aquí.",
  "tut.mrcHint1": "La persona de la imagen 1, el lugar de la 5, más una prohibición explícita. Decir qué no tomar es tan esencial como decir qué tomar.",
  "tut.mrcHint2": "Un objeto de la imagen 2, más una indicación que ninguna de las cinco fuentes aporta.",
  "tut.mrcHint3": "Un detalle de la imagen 3, restringido a un lado del rostro. La otra mejilla se describe como limpia.",
  "tut.mrcHint4": "La prenda completa de la imagen 4, reproducida con exactitud.",
  "tut.mrcHint5": "Solo un atributo. El color de la camiseta se toma de la imagen 5, no la camiseta en sí.",
  "tut.mrcAddRefsTitle": "Añade tus referencias",
  "tut.mrcAddRefsSub": "El orden define el número del token",
  "tut.mrcWritePromptTitle": "Escribe el prompt",
  "tut.mrcWritePromptSub": "Pasa el cursor sobre un token para ver qué toma",
  "tut.mrcGenerateSub": "Una imagen, cinco fuentes",
  "tut.mrcMakeItYours": "Hazlo tuyo",
  "tut.mrcClosing1Body": "Cambia cualquier archivo subido por una imagen tuya y ejecuta de nuevo. Los tokens siguen funcionando, porque apuntan a posiciones, no a archivos.",
  "tut.mrcClosing2Eyebrow": "Si algo sale mal",
  "tut.mrcClosing2Body": "Revisa el orden de las referencias antes de reescribir el prompt. El número indica la posición, no el nombre.",
  "tut.mrcClosing3Eyebrow": "Para probar una referencia",
  "tut.mrcClosing3Body": "Cámbiala, ejecuta de nuevo, compara. Una variable a la vez: ese es todo el método.",
  "tut.pnLesson1Title": "Conoce el nodo «Persona»",
  "tut.pnLesson1Sub": "Las elecciones se convierten en un prompt escrito",
  "tut.pnLesson1Body": "Elige los atributos y el nodo escribe por ti el prompt del personaje. Abre el «Prompt final» en el nodo «Generar imagen» para ver exactamente qué se envía al modelo.",
  "tut.pnLesson1Callout": "Pruébalo: cambia un atributo y mira cómo se actualiza el prompt. Todo lo que escribas en el campo «Prompt» se combina con él.",
  "tut.pnLesson2Title": "El mismo nodo, otro personaje",
  "tut.pnLesson2Sub": "Cambia las elecciones y cambia todo",
  "tut.pnLesson2Body": "El mismo nodo «Persona», atributos distintos, un resultado completamente diferente. El paso 1 dio un street style editorial; aquí, el mismo nodo da un retrato íntimo en un interior.",
  "tut.pnLesson3Title": "Combina nodos para controlar toda la escena",
  "tut.pnLesson3Sub": "Escena, encuadre, ambiente, personaje",
  "tut.pnLesson3Body": "La misma «Persona», ahora con «Fondo de estudio», «Encuadre» y «Ambiente» en capas. Cada nodo añade su propia descripción al «Prompt final».",
  "tut.pnLesson3Closing": "Mismo modelo, una toma totalmente distinta. Cambia un bloque y ejecuta de nuevo.",
  "tut.pnOrderScene": "escena",
  "tut.pnOrderFraming": "encuadre",
  "tut.pnOrderMood": "ambiente",
  "tut.pnOrderCharacter": "personaje",
  "tut.pnRailStep1Sub": "Siete elecciones se convierten en un prompt escrito",
  "tut.pnRailStep3Title": "Combina nodos para controlar la escena",
  "tut.pnRailStep3Sub": "«Fondo de estudio», «Encuadre» y «Ambiente» por encima",
  "tut.pnNoteEyebrow": "El patrón",
  "tut.pnNoteBody": "Crea imágenes con bloques modulares. Cambia cualquier nodo para iterar rápido.",
  "tut.iedNavyName": "Chaqueta azul marino",
  "tut.iedSubWritten": "Una instrucción escrita",
  "tut.iedNavyWhy": "El tipo de edición más simple: di qué cambiar y qué dejar como está. Precisamente nombrar lo que quieres conservar evita que el modelo redibuje el rostro junto con la chaqueta.",
  "tut.iedGoldenName": "Hora dorada",
  "tut.iedSubLighting": "Controlada por un nodo «Iluminación»",
  "tut.iedGoldenWhy": "Ningún prompt. El nodo «Iluminación» guarda la elección y la edición la lee, así que cambiar la iluminación de la toma es elegir una opción de un menú, no acertar con una frase.",
  "tut.iedTealName": "Verde azulado y naranja",
  "tut.iedSubColor": "Controlado por un nodo «Color / look»",
  "tut.iedTealWhy": "Una corrección de color, no un repintado. La misma imagen con un look de cine aplicado: el tipo de cambio que describirías mal en tres líneas de prompt.",
  "tut.iedAnimeName": "Anime, pintado",
  "tut.iedSubTwoStyles": "Dos nodos «Estilo» a la vez",
  "tut.iedAnimeWhy": "Dos nodos «Estilo» alimentan esta edición y el resultado mezcla ambos. El estilo no es un espacio único: combínalos y obtendrás un look que ninguno describe por sí solo.",
  "tut.iedAtomicName": "Era atómica, años 50",
  "tut.iedSubEra": "Controlada por un nodo «Época»",
  "tut.iedAtomicWhy": "Una época trae vestuario, paleta y película juntos. Esta edición también usa un modelo distinto al de las vecinas, lo cual es una decisión de cada nodo, no un ajuste de todo el lienzo.",
  "tut.iedCyberName": "Cyberpunk",
  "tut.iedSubStyle": "Controlado por un nodo «Estilo»",
  "tut.iedCyberWhy": "El mismo nodo «Estilo» de la edición de anime, con otro valor. Un único tipo de nodo cubre todo el catálogo, así que probar otro look lleva un clic.",
  "tut.ied85mmName": "Retrato a 85 mm",
  "tut.iedSubLens": "Controlado por un nodo «Lente»",
  "tut.ied85mmWhy": "Óptica, no contenido. La distancia focal cambia la compresión y la profundidad de campo: el sujeto sigue intacto y la fotografía pasa a ser otra fotografía.",
  "tut.iedNoBgName": "Fondo eliminado",
  "tut.iedSubNoSettings": "Sin ningún ajuste",
  "tut.iedNoBgWhy": "Nada que configurar y nada que escribir. Extrae el sujeto sobre transparencia, listo para colocarlo sobre cualquier cosa.",
  "tut.iedTokyoName": "Tokio de noche",
  "tut.iedTokyoWhy": "Cambiar el fondo exige dos cosas a la vez: el nuevo lugar y la iluminación del sujeto ajustada a ese lugar. Si pides solo lo primero, el aspecto de recorte delata el montaje.",
  "tut.iedHeadline": "Entra una imagen. Salen nueve ediciones distintas.",
  "tut.iedSubline": "Todas las ediciones leen el mismo original, así que nada se acumula y nada se degrada. Haz clic en cualquier resultado para ver exactamente qué lo produjo.",
  "tut.iedChipEdits": "9 ediciones",
  "tut.iedChipSharedOriginal": "1 original compartido",
  "tut.iedChipNonDestructive": "nada es destructivo",
  "tut.iedInSub": "Generada una vez y nunca más modificada",
  "tut.iedOutSub": "Haz clic en una para ver qué la generó",
  "tut.iedCriticLine": "Evalúa el original antes de que gastes nada en editarlo.",
  "tut.iedNoSettings": "Sin ajustes",
  "tut.ccvHeadline": "Entra un fotograma. Salen diez ángulos del mismo momento.",
  "tut.ccvSubline": "El personaje, el vestuario, el lugar y la luz nunca cambian. Solo cambia la cámara. Ves la lista de tomas antes de gastar nada y puedes reescribir cualquier línea.",
  "tut.ccvChipNodes": "6 nodos, no 25",
  "tut.ccvChipCuttable": "montable como secuencia",
