  "tut.ccvInTitle": "El fotograma de referencia",
  "tut.ccvInSub": "Una imagen. Esta es la escena.",
  "tut.ccvRefPromptEyebrow": "Prompt de referencia",
  "tut.ccvBriefEyebrow": "El briefing de cobertura · edítalo para cambiar el plan",
  "tut.ccvBriefRule1": "Orden real de cobertura: plano general, dos planos medios, dos primeros planos, plano sobre el hombro, contraplano, plano detalle, ángulo dinámico, perfil.",
  "tut.ccvBriefRule2": "Un ángulo de cámara por línea. Nunca combines dos términos de ángulo.",
  "tut.ccvBriefRule3": "Posición de la cámara, no movimiento. El movimiento se añade después.",
  "tut.ccvBriefRule4": "La dirección en pantalla se mantiene constante, para que los cortes no den saltos.",
  "tut.ccvBriefRule5": "Deja espacio para respirar. Cada fotograma debe funcionar como fotograma inicial de una animación.",
  "tut.ccvListTitle": "La lista de tomas",
  "tut.ccvListSub": "{count} líneas, editables antes de cualquier gasto",
