  "tut.promptEyebrow": "PROMPT",
  "tut.ocHeadline": "Dos imágenes. Cinco recetas. Sin máscaras, sin capas.",
  "tut.ocSubline": "Todas las recetas de abajo leen las mismas dos fuentes. Lo que cambia es qué parte de cada una nombras y con qué número la nombras. Esa es toda la técnica.",
  "tut.ocChipNoMask": "nada se enmascara",
  "tut.ocInTitle": "Dos fuentes",
  "tut.ocInSub": "Una generada, una subida",
  "tut.ocRoleGenerated": "toma de pasarela generada",
  "tut.ocRoleUploaded": "toma de estudio subida",
  "tut.ocSameTwoEyebrow": "LAS MISMAS DOS, SIEMPRE",
  "tut.ocSameTwoBody": "Las cinco recetas están conectadas a estas dos imágenes. No se vuelve a subir nada y no se edita nada entre ejecuciones.",
  "tut.ocRecipesTitle": "Cinco recetas",
  "tut.ocRecipesSub": "Una línea de prompt cada una",
  "tut.ocRecipesMeta": "HAZ CLIC EN UNA",
  "tut.ocTakesEyebrow": "LO QUE USA ESTA RECETA",
  "tut.ocNodeEyebrow": "NODO",
  "tut.ocR1Name": "El rostro de una, el cuerpo de la otra",
  "tut.ocR1OutTitle": "Un cuerpo, otro rostro",
  "tut.ocR1OutSub": "Receta 1 · las dos referencias con calificador",
  "tut.ocR1LessonKind": "EL PUNTO DE PARTIDA",
  "tut.ocR1Lesson": "Dos referencias con calificador construyen una sola persona a partir de dos imágenes. Ninguna llega completa.",
  "tut.ocR1Note1": "Pose, complexión y encuadre. Su rostro no se usa.",
  "tut.ocR1Note2": "Solo pasa el rostro.",
  "tut.ocR2Name": "Cambia el orden, cambia el resultado",
  "tut.ocR2OutTitle": "La misma receta, invertida",
  "tut.ocR2OutSub": "Receta 2 · números intercambiados",
  "tut.ocR2LessonKind": "EL OBJETIVO DE TODA LA PLANTILLA",
  "tut.ocR2Lesson": "Los mismos calificadores, números intercambiados. Qué imagen es la 1 y cuál es la 2 decide quién termina apareciendo en la foto.",
  "tut.ocR2Note1": "Ahora la segunda fuente aporta el cuerpo.",
  "tut.ocR2Note2": "Y la primera aporta solo el rostro.",
  "tut.ocR3Name": "Conserva el escenario, cambia a la estrella",
  "tut.ocR3OutTitle": "El mismo lugar, otra persona",
  "tut.ocR3OutSub": "Receta 3 · calificador background",
  "tut.ocR3LessonKind": "OTRO CALIFICADOR",
  "tut.ocR3Lesson": "background pide el lugar sin quien lo ocupa. Es útil cuando el lugar es lo que quieres conservar.",
  "tut.ocR3Note1": "La pasarela y su iluminación, sin la modelo.",
  "tut.ocR3Note2": "La persona que ahora está en ella.",
  "tut.ocR4Name": "De la pasarela al estudio",
  "tut.ocR4OutTitle": "La misma persona, otro lugar",
  "tut.ocR4OutSub": "Receta 4 · el espejo de la receta 3",
  "tut.ocR4LessonKind": "LEE LA PREPOSICIÓN",
  "tut.ocR4Lesson": "settings es lo inverso de la receta anterior: conserva a la persona y la lleva a otro sitio. La palabra in es la que hace la colocación.",
  "tut.ocR4Note1": "El sujeto, trasladado completo.",
  "tut.ocR4Note2": "El fondo del estudio y su luz.",
  "tut.ocR5Name": "Su chaqueta, su estudio, tu modelo",
  "tut.ocR5OutTitle": "Tres partes, dos imágenes",
  "tut.ocR5OutSub": "Receta 5 · dos calificadores de una sola fuente",
  "tut.ocR5LessonKind": "APILADO",
  "tut.ocR5Lesson": "La misma fuente puede nombrarse dos veces con calificadores distintos. Aquí la imagen 2 aporta una prenda y un lugar, en una sola línea.",
  "tut.ocR5Note1": "El sujeto.",
  "tut.ocR5Note2": "Una prenda, extraída por sí sola.",
  "tut.ocR5Note3": "Y la sala donde se fotografió.",
  "tut.ocRecipeAsWritten": "Receta {n} · tal como está escrita en el nodo",
  "tut.ocLessonKindOther": "OTRA COMBINACIÓN",
  "tut.ocLessonOther": "Lee el prompt: qué fuente se nombra, qué parte de ella y con qué número.",
  "tut.ocAddsUpEyebrow": "CÓMO ENCAJA TODO",
  "tut.ocResultChip": "EL RESULTADO",
  "tut.ocResultCaption": "una imagen, sin máscaras",
