  "tut.ocCropFace": "solo el rostro",
  "tut.ocCropPerson": "la figura completa",
  "tut.ocCropBackground": "la pasarela que la rodea",
  "tut.ocCropJacket": "una prenda",
  "tut.ocCropSettings": "solo la sala",
  "tut.ocBlankTile": "SIN PERSONA, SOLO LA SALA",
  "tut.ocCropPart": "la parte «{part}»",
  "tut.ocCropSource": "la fuente",
  "tut.sunoChangeStart": "El punto de partida — cada opción elegida en un menú desplegable.",
  "tut.listAnd": "{a} y {b}",
  "tut.sunoChangeAdded": "Añadido: {names}.",
  "tut.sunoChangeDropped": "Quitado: {names}.",
  "tut.sunoChangeInstrumental": "Cambió a instrumental — sin voces.",
  "tut.sunoChangeVocals": "Las voces volvieron.",
