  "tut.regMrcTitle": "Control con varias referencias",
  "tut.regMrcSummary": "Cinco imágenes de origen, una imagen generada. Señala una imagen en lugar de describirla.",
  "tut.regMrcStep1Sub": "Cinco subidas en un solo conector «Referencias»",
  "tut.regMrcStep2Sub": "Señala posiciones con @image:N",
  "tut.regMrcStep4Sub": "Cambia una imagen, vuelve a ejecutar, compara",
  "tut.regWdSummary": "Una frase se convirtió en imagen, la imagen se convirtió en movimiento y una línea de voz lo unió todo. Este lienzo es una ejecución terminada.",
  "tut.regWdStep2Sub": "Z-Image, lo primero que vale la pena ejecutar",
  "tut.regWdStep3Sub": "Seedance 2 Fast, 5 segundos",
  "tut.regWdStep4Sub": "Una segunda cadena, ejecutándose en paralelo",
  "tut.regWdStep5Sub": "Video y voz combinados",
  "tut.regPnTitle": "Primeros pasos con el nodo «Persona»",
  "tut.regPnSummary": "Elige atributos en menús desplegables y el nodo escribe el prompt del personaje por ti. Tres ejecuciones, de un solo nodo a una combinación completa.",
  "tut.regPnChip": "3 ejecuciones",
  "tut.regSunoTitle": "Crear música con nodos",
  "tut.regSunoSummary": "No escribes la descripción de una canción. Eliges opciones y los nodos la escriben por ti.",
  "tut.regSunoChip": "7 ejecuciones",
  "tut.regSunoNoteEyebrow": "Cómo usar este tutorial",
  "tut.regSunoNoteBody": "Recorre las ejecuciones. Cada una cambia exactamente una cosa respecto a la anterior, así que la diferencia que oyes es la opción que se movió.",
  "tut.regSunoStep1Title": "Elige opciones en los nodos de estilo",
  "tut.regSunoStep1Sub": "Género, ambiente, instrumentación, voz",
  "tut.regSunoStep2Title": "Envíalas al nodo «Generar con Suno»",
  "tut.regSunoStep2Sub": "Las elecciones se convierten en la descripción del estilo",
  "tut.regSunoStep3Title": "Obtén una pista terminada",
  "tut.regSunoStep3Sub": "Escúchala y luego cambia una opción",
  "tut.regApTitle": "Piloto automático para redes sociales",
  "tut.regApSummary": "Pega una idea. Siete nodos la dividen en diapositivas, dibujan una imagen para cada una, escriben el texto de acompañamiento y la publican.",
  "tut.regApStep1Title": "Dale un bloque de texto",
  "tut.regApStep1Sub": "No hay nada más que rellenar",
  "tut.regApStep2Title": "Escribe y dibuja diez diapositivas",
  "tut.regApStep2Sub": "Texto por diapositiva, una imagen para cada una",
  "tut.regApStep3Title": "Escribe el texto de acompañamiento y publica",
  "tut.regApStep3Sub": "Con formato para el feed y luego publicado",
  "tut.regIedTitle": "Primeros pasos con la edición de imágenes",
  "tut.regIedSummary": "Una imagen se genera una sola vez y nueve ediciones independientes leen ese mismo original. Nada se acumula, así que nada se degrada.",
  "tut.regIedNoteEyebrow": "Esto es una ramificación, no una cadena",
  "tut.regIedNoteBody": "Cada edición lee el original directamente. Cambia una y las otras ocho no se ven afectadas — esa es toda la idea.",
  "tut.regIedStep1Sub": "Generada una vez y luego evaluada",
  "tut.regIedStep2Title": "Nueve ediciones, una fuente",
  "tut.regIedStep2Sub": "Cada una lee la misma imagen",
  "tut.regIedStep3Title": "Sigue cualquier resultado",
  "tut.regIedStep3Sub": "Haz clic en una miniatura para ver qué la generó",
  "tut.regCcvTitle": "Cobertura de cámara — un fotograma, diez ángulos",
  "tut.regCcvSummary": "Entra un fotograma de referencia, salen diez tomas de la misma escena. Solo cambia la cámara — un plan de cobertura de director que puedes montar, a partir de una sola imagen.",
  "tut.regCcvChip": "10 tomas",
  "tut.regCcvNoteEyebrow": "La palanca es la lista",
  "tut.regCcvNoteBody": "Un nodo de imagen, diez filas. La lista lo ramifica, así que diez tomas cuestan seis nodos, no veinticinco — y editar una línea vuelve a rodar un solo ángulo.",
  "tut.regCcvStep1Sub": "Una imagen y el briefing que rige el plan",
  "tut.regCcvStep2Sub": "Diez líneas que puedes leer — y reescribir — antes de gastar nada",
  "tut.regCcvStep3Sub": "Diez tomas de un mismo momento, desde un solo nodo de imagen",
  "tut.regOcTitle": "Un personaje, cualquier escena",
  "tut.regOcSummary": "Dos imágenes de origen, cinco recetas de una línea, sin máscaras y sin capas. Lo que cambia entre los resultados es qué parte de cada fuente nombras — y con qué número la nombras.",
  "tut.regOcChip": "5 recetas",
  "tut.regOcNoteEyebrow": "Lee los números, no las imágenes",
  "tut.regOcNoteBody": "{image:1} y {image:2} son posiciones en la lista de referencias — el orden en que se conectaron las fuentes —, no los nombres de los nodos. La receta 2 es la receta 1 con los números intercambiados, y esa es toda la lección.",
  "tut.regOcStep1Sub": "Una generada, una subida — {image:1} y {image:2}",
  "tut.regOcStep2Sub": "Haz clic en una: qué toma de cada fuente y qué enseña",
  "tut.regOcStep3Sub": "La imagen y cómo encajan en ella las partes prestadas",
