  "adminExpunge.deletedExecutions": "Cada ejecución de flujo de trabajo de cada ejecución (incluidas sus reejecuciones, los renderizados finales y las ejecuciones de componentes): los estados de sus nodos (los resultados generados), las entradas que aplicó y su mensaje de error. El registro propio de cada ejecución de componente también pierde sus entradas, sus resultados editados y su nombre",
