  "apiErr.measureClip": "No se pudo medir el video",
  "vidcfg.videoMaskDesc": "Rastrea el sujeto que describes a lo largo del video conectado (SAM 3.1 o SAM 3) y genera un video de máscara en blanco y negro: el blanco es el sujeto. Conéctalo a la entrada «Máscara» del nodo «Composición por máscara».",
  "vidcfg.videoMaskPromptExamples": "p. ej.: «el perro», «la mujer del abrigo rojo», «el auto»",
  "vidcfg.videoMaskPricingHint": "El precio depende de la duración del clip a 30 fps, así que un clip a 60 fps cuenta el doble. Clips de hasta 5 minutos. SAM 3 cuesta la mitad que SAM 3.1.",
  "vidcfg.videoMaskHoldLastMask": "Mantener la máscara cuando se pierde el sujeto",
  "vidcfg.videoMaskHoldLastMaskHint": "Cuando el sujeto queda oculto un momento (una mano delante de un rostro), conserva su última máscara en lugar de un fotograma vacío, hasta 1 segundo.",
  "vidcfg.videoMaskMinSubjectHeight": "Ignorar sujetos menores que (% de la altura del fotograma)",
  "vidcfg.videoMaskMinSubjectHeightOff": "Desactivado",
  "vidcfg.videoMaskMinSubjectHeightHint": "Descarta en cada fotograma todo sujeto más bajo que esta proporción de la altura del fotograma (por ejemplo, los rostros de los extras detrás de la persona principal). 0 lo desactiva.",
  "vidcfg.videoMaskMaxSubjectHeight": "Ignorar sujetos mayores que (% de la altura del fotograma)",
  "vidcfg.videoMaskMaxSubjectHeightHint": "Descarta en cada fotograma todo sujeto más alto que esta proporción de la altura del fotograma, por ejemplo para conservar solo los rostros pequeños del fondo. 0 lo desactiva.",
  "vidcfg.videoMaskSizeBandEmpty": "«Ignorar sujetos menores que» está por encima de «Ignorar sujetos mayores que»: no se puede conservar ningún sujeto. Reduce uno de los dos.",
  "vidcfg.videoMaskZone": "Zona",
  "vidcfg.videoMaskZoneLeft": "Margen izquierdo (%)",
  "vidcfg.videoMaskZoneRight": "Margen derecho (%)",
  "vidcfg.videoMaskZoneTop": "Margen superior (%)",
  "vidcfg.videoMaskZoneBottom": "Margen inferior (%)",
  "vidcfg.videoMaskZoneHint": "Conserva solo los sujetos cuyo centro queda dentro del fotograma menos estos márgenes, por ejemplo para descartar rostros en los bordes de la imagen. Cada lado de 0 a 49 %; con todo en 0 se desactiva.",
  "vidcfg.videoMaskPerShot": "Detectar de nuevo tras cada corte",
  "vidcfg.videoMaskPerShotHint": "Vuelve a encontrar el sujeto en cada toma, de modo que un rostro u objeto nuevo tras un corte también recibe máscara. Una máscara mantenida nunca cruza un corte. En un clip sin cortes, es la misma máscara, ajustada al número exacto de fotogramas del clip.",
  "vidcfg.videoMaskRedetect": "Detectar de nuevo cada (segundos)",
  "vidcfg.videoMaskRedetectValue": "{sec} s",
  "vidcfg.videoMaskRedetectHint": "También vuelve a encontrar el sujeto cada pocos segundos, de modo que quien entra en escena o se gira hacia la cámara a mitad de una toma recibe máscara desde la siguiente comprobación. Cada comprobación es una solicitud más al modelo, así que la ejecución tarda más; el precio es el mismo. Una máscara mantenida continúa a través de estas comprobaciones (solo un corte la interrumpe). 0 lo desactiva.",
  "proccfg.maskCompositeDesc": "Coloca el video de primer plano sobre el video de fondo a través del video de máscara: el blanco muestra el primer plano y el negro muestra el fondo. El resultado conserva el tamaño, la velocidad de fotogramas y la duración del primer plano, y se cobra por cada 5 segundos iniciados. Con Pixelar o Desenfocar no hace falta primer plano y el resultado sigue al fondo.",
  "proccfg.maskCompositeInvert": "Invertir máscara",
  "proccfg.maskCompositeInvertHint": "Intercambia los lados: el blanco pasa a mostrar el fondo.",
  "proccfg.maskCompositeFeather": "Suavizado: {n} px",
  "proccfg.maskCompositeFeatherHint": "Suaviza el borde de la máscara. Con 0, el borde queda nítido.",
  "proccfg.maskCompositeGrow": "Expandir / reducir: {n} px",
  "proccfg.maskCompositeGrowHint": "Un valor positivo expande el área blanca y un valor negativo la reduce.",
  "proccfg.maskCompositeOpacity": "Opacidad: {n}%",
  "proccfg.maskCompositeOpacityHint": "Cuánto cubre el relleno (el primer plano, o el fondo pixelado / desenfocado) al fondo dentro de la máscara. Al 100% lo reemplaza allí; con valores menores se mezclan.",
  "proccfg.maskCompositeFill": "Relleno",
  "proccfg.maskCompositeFillVideo": "Video (el primer plano)",
  "proccfg.maskCompositeFillPixelate": "Pixelar",
  "proccfg.maskCompositeFillBlur": "Desenfocar",
  "proccfg.maskCompositeFillHint": "Lo que rellena el área enmascarada. Pixelar y Desenfocar usan el propio fondo, así que no hace falta primer plano, y el resultado sigue el tamaño, la velocidad de fotogramas y la duración del fondo.",
  "proccfg.maskCompositePixelSizePct": "Tamaño del bloque (% del ancho): {n}%",
  "proccfg.maskCompositePixelSizePctHint": "El tamaño de cada bloque, como proporción del ancho del video, para que se vea igual en cualquier resolución. Los bloques más grandes ocultan más detalle.",
  "proccfg.maskCompositeBlurStrengthPct": "Intensidad del desenfoque (% del ancho): {n}%",
